/* LZMA (xom oqim, lc=0 lp=0 pb=0) dekoderi */
typedef struct { uint32_t range, code; const uint8_t *in, *end; } LzRc;
static inline uint32_t lz_bit(LzRc *r, uint16_t *p) {
    uint32_t bound = (r->range >> 11) * *p, b;
    if (r->code < bound) { r->range = bound; *p += (2048 - *p) >> 5; b = 0; }
    else { r->range -= bound; r->code -= bound; *p -= *p >> 5; b = 1; }
    if (r->range < (1u << 24)) { r->range <<= 8; r->code = (r->code << 8) | (r->in < r->end ? *r->in++ : 0); }
    return b;
}
static uint32_t lz_tree(LzRc *r, uint16_t *p, int nb) {
    uint32_t m = 1;
    for (int i = 0; i < nb; i++) m = (m << 1) | lz_bit(r, p + m);
    return m - (1u << nb);
}
static uint32_t lz_rtree(LzRc *r, uint16_t *p, int nb) {
    uint32_t m = 1, s = 0;
    for (int i = 0; i < nb; i++) { uint32_t b = lz_bit(r, p + m); m = (m << 1) | b; s |= b << i; }
    return s;
}
typedef struct { uint16_t ch, ch2, low[16][8], mid[16][8], high[256]; } LzLen;
static uint32_t lz_len(LzRc *r, LzLen *l, int ps) {
    if (!lz_bit(r, &l->ch)) return lz_tree(r, l->low[ps], 3);
    if (!lz_bit(r, &l->ch2)) return 8 + lz_tree(r, l->mid[ps], 3);
    return 16 + lz_tree(r, l->high, 8);
}
static int lzma_decode(const uint8_t *in, size_t inn, uint8_t *out, size_t dn) {
    if (inn < 5) return 0;
    static uint16_t IsMatch[12 << 4], IsRep[12], G0[12], G1[12], G2[12], Rep0L[12 << 4], Slot[4][64], PosD[115], Align[16], Lit[0x300];
    static LzLen LenD, RepD;
    uint16_t *all[] = {IsMatch, IsRep, G0, G1, G2, Rep0L, &Slot[0][0], PosD, Align, Lit, (uint16_t *)&LenD, (uint16_t *)&RepD};
    size_t sz[] = {sizeof IsMatch, sizeof IsRep, sizeof G0, sizeof G1, sizeof G2, sizeof Rep0L, sizeof Slot, sizeof PosD, sizeof Align, sizeof Lit, sizeof LenD, sizeof RepD};
    for (int i = 0; i < 12; i++) for (size_t k = 0; k < sz[i] / 2; k++) all[i][k] = 1024;
    LzRc r; r.in = in + 5; r.end = in + inn; r.range = 0xFFFFFFFFu; r.code = 0;
    for (int i = 1; i < 5; i++) r.code = (r.code << 8) | in[i];
    uint32_t rep0 = 0, rep1 = 0, rep2 = 0, rep3 = 0; int state = 0; size_t o = 0;
    while (o < dn) {
        if (r.in > r.end + 8) return 0;
        if (!lz_bit(&r, &IsMatch[state << 4])) {   /* pb=0 -> posState=0 */
            uint16_t *pr = Lit; uint32_t sym = 1;
            if (state >= 7 && o > rep0) {
                uint32_t mb = out[o - rep0 - 1], bit;
                do { uint32_t mbit = (mb >> 7) & 1; mb <<= 1; bit = lz_bit(&r, pr + ((1 + mbit) << 8) + sym); sym = (sym << 1) | bit; if (mbit != bit) break; } while (sym < 0x100);
            }
            while (sym < 0x100) sym = (sym << 1) | lz_bit(&r, pr + sym);
            out[o++] = (uint8_t)sym;
            state = state < 4 ? 0 : (state < 10 ? state - 3 : state - 6);
            continue;
        }
        uint32_t len;
        if (!lz_bit(&r, &IsRep[state])) {
            rep3 = rep2; rep2 = rep1; rep1 = rep0;
            len = lz_len(&r, &LenD, 0);
            state = state < 7 ? 7 : 10;
            uint32_t ls = len < 4 ? len : 3;
            uint32_t slot = lz_tree(&r, Slot[ls], 6), dist;
            if (slot < 4) dist = slot;
            else {
                int nd = (int)(slot >> 1) - 1;
                dist = (2 | (slot & 1)) << nd;
                if (slot < 14) dist += lz_rtree(&r, PosD + dist - slot, nd);
                else {
                    uint32_t res = 0;
                    for (int i = 0; i < nd - 4; i++) {
                        r.range >>= 1; r.code -= r.range;
                        uint32_t t = 0 - (r.code >> 31); r.code += r.range & t;
                        if (r.range < (1u << 24)) { r.range <<= 8; r.code = (r.code << 8) | (r.in < r.end ? *r.in++ : 0); }
                        res = (res << 1) + t + 1;
                    }
                    dist += res << 4;
                    dist += lz_rtree(&r, Align, 4);
                }
            }
            rep0 = dist;
            if (rep0 == 0xFFFFFFFFu) break;
        } else {
            if (o == 0) return 0;
            if (!lz_bit(&r, &G0[state])) {
                if (!lz_bit(&r, &Rep0L[state << 4])) { state = state < 7 ? 9 : 11; out[o] = out[o - rep0 - 1]; o++; continue; }
            } else {
                uint32_t dist;
                if (!lz_bit(&r, &G1[state])) dist = rep1;
                else { if (!lz_bit(&r, &G2[state])) dist = rep2; else { dist = rep3; rep3 = rep2; } rep2 = rep1; }
                rep1 = rep0; rep0 = dist;
            }
            len = lz_len(&r, &RepD, 0);
            state = state < 7 ? 8 : 11;
        }
        len += 2;
        if (rep0 >= o || o + len > dn) return 0;
        for (uint32_t k = 0; k < len; k++) { out[o] = out[o - rep0 - 1]; o++; }
    }
    return o == dn;
}

#define MT_MAXC 40
typedef struct { int c[4]; long long n[4]; size_t base, size; } MtC;
static MtC MTC[MT_MAXC];
static int MTN = 0;
static int mt_idx[4][4][4][4];
static size_t mt_total = 0;
static uint8_t *mt_data = NULL;
static int mt_state = 0;
static volatile int mt_done = 0, mt_lock = 0;

static void mt_classes_init(void) {
    memset(mt_idx, -1, sizeof mt_idx);
    MTN = 0; mt_total = 0;
    for (int a = 1; a <= 3; a++) for (int b = 1; b <= 3; b++) {
        if (a + b > 4) continue;
        for (int om = 0; om <= a; om++) for (int xm = 0; xm <= b; xm++) {
            if (om + xm == 0) continue;           /* faqat damkalar eski bazada */
            MtC *C = &MTC[MTN];
            C->c[0] = om; C->c[1] = a - om; C->c[2] = xm; C->c[3] = b - xm;
            size_t sz = 1;
            for (int g = 0; g < 4; g++) { C->n[g] = BN[32][C->c[g]]; sz *= (size_t)C->n[g]; }
            C->base = mt_total; C->size = sz; mt_total += sz;
            mt_idx[C->c[0]][C->c[1]][C->c[2]][C->c[3]] = MTN++;
        }
    }
}

/* taxtadagi holatni bazadagi (sinf, indeks) ga aylantiradi; yuruvchi doim "o'z" (yuqoriga yuradi) */
static int mt_locate(int side, int *cls, size_t *idx) {
    int g[4][3], c[4] = {0, 0, 0, 0};
    for (int sq = 0; sq < 64; sq++) {
        int p = B[sq];
        if (!p) continue;
        int own = p * side > 0;
        int s2 = side > 0 ? sq : 63 - sq;
        int t = (p == 1 || p == -1) ? 0 : 1;
        int grp = (own ? 0 : 2) + t;
        if (c[grp] >= 3) return 0;
        g[grp][c[grp]++] = DKI[s2];
    }
    if (c[0] + c[1] == 0 || c[2] + c[3] == 0 || c[0] + c[1] + c[2] + c[3] > 4 || c[0] + c[2] == 0) return 0;
    int ci = mt_idx[c[0]][c[1]][c[2]][c[3]];
    if (ci < 0) return 0;
    const MtC *C = &MTC[ci];
    size_t key = 0;
    for (int k = 0; k < 4; k++) {
        int *s = g[k], n = c[k], x, i, j;
        for (i = 1; i < n; i++) { x = s[i]; for (j = i - 1; j >= 0 && s[j] > x; j--) s[j + 1] = s[j]; s[j + 1] = x; }
        int r = 0;
        for (i = 0; i < n; i++) r += BN[s[i]][i + 1];
        key = key * (size_t)C->n[k] + (size_t)r;
    }
    *cls = ci; *idx = C->base + key;
    return 1;
}

static int mt_init(void) {
    mt_state = -1;
    mt_classes_init();
    if (getenv("DMT")) return 0;   /* sinov: aralash bazani o'chirish */
    size_t L = strlen(TBMIX);
    if (!MT_ON || L == 0) return 0;
    static const char *AL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int8_t dec[256];
    memset(dec, -1, sizeof dec);
    for (int i = 0; i < 64; i++) dec[(uint8_t)AL[i]] = (int8_t)i;
    uint8_t *raw = (uint8_t *)malloc(L / 4 * 3 + 8);
    uint8_t *out = (uint8_t *)malloc(mt_total + 8);
    if (!raw || !out) return 0;
    size_t rn = 0; uint32_t acc = 0; int bits = 0;
    for (size_t i = 0; i < L; i++) {
        int v = dec[(uint8_t)TBMIX[i]];
        if (v < 0) continue;
        acc = (acc << 6) | (uint32_t)v; bits += 6;
        if (bits >= 8) { bits -= 8; raw[rn++] = (uint8_t)(acc >> bits); acc &= (1u << bits) - 1; }
    }
    if (rn < 14 || !lzma_decode(raw + 13, rn - 13, out, mt_total)) { free(raw); free(out); return 0; }
    free(raw);
    size_t o = mt_total;
    if (o != mt_total) { free(out); return 0; }
    mt_data = out;
    mt_state = 1;
    return 1;
}
static void mt_ensure(void) {
    while (__sync_lock_test_and_set(&mt_lock, 1)) { }
    if (!mt_done) { mt_init(); __sync_synchronize(); mt_done = 1; }
    __sync_lock_release(&mt_lock);
}
/* val: 0 durang, >0 g'alaba (yarim yurish), <0 mag'lubiyat (-val-1 yarim yurish) */
static int mt_probe(int side, int *val) {
    if (!MT_ON) return 0;
    int ci; size_t idx;
    if (!mt_locate(side, &ci, &idx)) return 0;
    if (!mt_done) mt_ensure();
    if (mt_state <= 0) return 0;
    int v = mt_data[idx];
    if (v == 0) *val = 0;
    else if (v < 128) *val = v;
    else *val = -(2 * (v - 128)) - 1;
    return 1;
}

static int T_FUT1 = 0, T_FUT2 = 0, T_LMRH = 0, T_LMP = 0, T_IID = 0;   /* sinov uchun env DSRCH="fut1,fut2,lmrh,lmp,iid" */
static void srch_env(void) {
    const char *e = getenv("DSRCH");
    if (!e) return;
    int v[5] = {0, 0, 0, 0, 0}, i = 0; char *q;
    while (i < 5) { long x = strtol(e, &q, 10); if (q == e) break; v[i++] = (int)x; e = q; while (*e == ',' || *e == ' ') e++; }
    T_FUT1 = v[0]; T_FUT2 = v[1]; T_LMRH = v[2]; T_LMP = v[3]; T_IID = v[4];
}
static int negamax(int side, int depth, int alpha, int beta, int ply) {
    nodes++;
    if ((nodes & 2047) == 0 && now_ms() > deadline) stopf = 1;
    if (stopf) return 0;
    if (NPCS <= 4) {
        int tv;
        if (kt_probe(side, &tv) || mt_probe(side, &tv)) {
            if (tv == 0) return 0;
            int d = ply + (tv > 0 ? tv : -tv - 1);
            if (d > 98) d = 98;
            return tv > 0 ? WIN - 100 - d : -(WIN - 100 - d);
        }
    }
    if (depth <= 0 && ply < MAXP - 2) {
        int q;
        if (!leaf_scan(side, &q) && !(q > 0 && NPCS == 4 && kt_lone(side))) {
            if (q == 0) return -WIN + ply;
            return side * eval() + P[P_MOB] * q;
        }
    }
    Move ml[MAXM];
    int n = gen(side, ml);
    if (n == 0) return -WIN + ply;
    int capture = ml[0].nc > 0;
    if (depth <= 0 && !capture) {
        if (NPCS == 4 && kt_lone(side)) depth = 1; /* yolg'iz damka: bola holatlar bazadan o'qiladi */
        else return side * eval() + P[P_MOB] * n;
    }
    if (ply >= MAXP - 2) return side * eval();

    uint64_t key = H ^ SK[side > 0];
    keys[ply] = key;
    for (int i = ply - 2; i >= 0; i -= 2)
        if (keys[i] == key) return 0; /* takrorlanish = durang */

    int ttf = -1, ttt = -1, ttn = -1;
    if (depth > 0) {
        TTE tmp; TTE *e = &tmp;
        if (tt_load(key, &tmp)) {
            ttf = e->from; ttt = e->to; ttn = e->n;
            if (e->depth >= depth) {
                int v = score_from_tt(e->score, ply);
                if (e->flag == 0) return v;
                if (e->flag == 1 && v >= beta) return v;
                if (e->flag == 2 && v <= alpha) return v;
            }
        }
    }

    int hs = side > 0;
    for (int i = 0; i < n; i++) {
        Move *m = &ml[i];
        if (m->from == ttf && m->to == ttt && m->nc == ttn) m->sc = 1000000;
        else if (m->nc) m->sc = 100000 + m->nc * 100;
        else {
            int k = (m->from << 6) | m->to;
            m->sc = hist[hs][m->from][m->to];
#if USE_CM
            if (ply > 0 && lastk[ply] >= 0 && cmv[hs][lastk[ply] >> 6][lastk[ply] & 63] == k) m->sc += 45000;
#endif
            if (killer[ply][0] == k) m->sc += 50000;
            else if (killer[ply][1] == k) m->sc += 40000;
        }
    }

    int ext = (n == 1) ? EXT_SINGLE : 0;
    int best = -INF, bi = -1, a0 = alpha;
    int futv = -INF;   /* futility: statik baho + chegara <= alpha bo'lsa tinch yurishlar kesiladi */
    if (depth <= 2 && !capture && n > 1 && alpha > -WIN / 2 && beta < WIN / 2) {
        int mg = depth == 1 ? T_FUT1 : T_FUT2;
        if (mg > 0) futv = side * eval() + mg;
    }
    for (int i = 0; i < n; i++) {
        int bj = i;
        for (int j = i + 1; j < n; j++) if (ml[j].sc > ml[bj].sc) bj = j;
        if (bj != i) { Move t = ml[i]; ml[i] = ml[bj]; ml[bj] = t; }
        Move *m = &ml[i];
        int promo_mv = m->king && B[m->from] == side;
        if (i > 0 && futv > -INF && futv <= alpha && !m->nc && !promo_mv && best > -WIN / 2) {
            if (futv > best) best = futv;
            continue;
        }
        if (T_LMP && i >= T_LMP + depth * 2 && depth <= 3 && !capture && !promo_mv && best > -WIN / 2 && m->sc < 40000) continue;
        make_s(side, m, ply);
        lastk[ply + 1] = (int16_t)((m->from << 6) | m->to);
        int sc;
        int nd = depth - 1 + ext;
        if (nd > 0) __builtin_prefetch(&TT[(H ^ SK[-side > 0]) & TT_MASK]);   /* bola tugun jadvalini oldindan keshga yuklash */
        if (i == 0) sc = -negamax(-side, nd, -beta, -alpha, ply + 1);
        else {
            int r = 0;
            if (USE_LMR && !capture && i >= LMR_I && depth >= 3 && !promo_mv) {
                r = 1;
                if (i >= LMR_J && depth >= 6) r = 2;
                if (T_LMRH && r > 0 && m->sc > T_LMRH) r--;
            }
            sc = -negamax(-side, nd - r, -alpha - 1, -alpha, ply + 1);
            if (r && sc > alpha && !stopf)
                sc = -negamax(-side, nd, -alpha - 1, -alpha, ply + 1);
            if (sc > alpha && sc < beta && !stopf)
                sc = -negamax(-side, nd, -beta, -alpha, ply + 1);
        }
        unmake_s(side, m, ply);
        if (stopf) return 0;
        if (sc > best) { best = sc; bi = i; }
        if (sc > alpha) alpha = sc;
        if (alpha >= beta) {
            if (!m->nc) {
                int k = (m->from << 6) | m->to;
                if (killer[ply][0] != k) { killer[ply][1] = killer[ply][0]; killer[ply][0] = k; }
                hist[hs][m->from][m->to] += depth * depth;
#if USE_CM
                if (ply > 0 && lastk[ply] >= 0) cmv[hs][lastk[ply] >> 6][lastk[ply] & 63] = (int16_t)k;
#endif
            }
            break;
        }
    }
    if (depth > 0 && bi >= 0) {
        TTE old;
        if (!tt_load(key, &old) || depth >= old.depth || (uint8_t)old.pad != (uint8_t)g_gen)
            tt_store(key, score_to_tt(best, ply), depth, best >= beta ? 1 : (best > a0 ? 0 : 2),
                     ml[bi].from, ml[bi].to, ml[bi].nc);
    }
    return best;
}

/* ------------------------------ perft (sinov) ------------------------------ */
static long long perft(int side, int d, int ply) {
    if (d == 0) return 1;
    Move ml[MAXM];
    int n = gen(side, ml);
    if (d == 1) return n;
    long long t = 0;
    for (int i = 0; i < n; i++) {
        make_s(side, &ml[i], ply);
        t += perft(-side, d - 1, ply + 1);
        unmake_s(side, &ml[i], ply);
    }
    return t;
}

/* ------------------------------ asosiy ------------------------------ */
static uint64_t board_hash(void) {
    uint64_t h = 0;
    for (int i = 0; i < 64; i++) if (B[i]) h ^= ZB[zi(B[i])][i];
    return h;
}


#define MAXTH 4
typedef struct { Move m; int pen; int pn; int8_t path[16]; } Root;
typedef struct {
    int tid, n;
    int8_t board0[64];
    Root *rm;
    long long t0, limit;
    Root bestr;
    int bestsc, bestdepth;
    long long nodes;
} TCtx;

static uint64_t board_hash(void);

/* ildiz qidiruvi: iterative deepening. tid==0 - asosiy oqim (natijani shu beradi), qolganlari TT ni to'ldirib yordam beradi */
static void run_root(void *arg) {
    TCtx *c = (TCtx *)arg;
    memcpy(B, c->board0, 64);
    H = board_hash();
    MP = MN = MK = 0; NPCS = 0;
    for (int i = 0; i < 64; i++) {
        if (B[i]) NPCS++;
        if (B[i] > 0) MP |= 1ULL << i; else if (B[i] < 0) MN |= 1ULL << i;
        if (B[i] == 2 || B[i] == -2) MK |= 1ULL << i;
    }
    nodes = 0;
    Root *rm = c->rm;
    int n = c->n;
    Root bestr = rm[0];
    int bestsc = 0, bestdepth = 0;
    int maxd = 60;
    { const char *e = getenv("DRDEPTH"); if (e) maxd = atoi(e) + 1; }
    for (int depth = 1 + (c->tid & 1); depth < maxd; depth++) {
        int alpha = -INF, beta = INF, bi = -1;
        int iter_best = -INF;
        for (int i = 2; i < n; i++) {
            Root t = rm[i]; int j = i - 1;
            while (j >= 1 && rm[j].m.sc < t.m.sc) { rm[j + 1] = rm[j]; j--; }
            rm[j + 1] = t;
        }
        keys[0] = H ^ SK[1];
        lastk[0] = -1;
        for (int i = 0; i < n && !stopf; i++) {
            make_s(1, &rm[i].m, 0);
            lastk[1] = (int16_t)((rm[i].m.from << 6) | rm[i].m.to);
            int sc, pp = rm[i].pen;
            int nd = depth - 1;
            if (i == 0) {
                sc = -negamax(-1, nd, -beta - pp, -alpha - pp, 1) - pp;
            } else {
                sc = -negamax(-1, nd, -(alpha + 1) - pp, -alpha - pp, 1) - pp;
                if (sc > alpha && !stopf)
                    sc = -negamax(-1, nd, -beta - pp, -alpha - pp, 1) - pp;
            }
            unmake_s(1, &rm[i].m, 0);
            if (stopf) break;
            rm[i].m.sc = sc;
            if (sc > iter_best) { iter_best = sc; bi = i; alpha = sc; }
        }
        if (bi < 0) break; /* hatto birinchi yurish tugamadi */
        Root bm = rm[bi];
        for (int k = bi; k > 0; k--) rm[k] = rm[k - 1];
        rm[0] = bm;
        bestr = bm; bestsc = iter_best;
        if (!stopf) bestdepth = depth;
        if (stopf) break;
        if (iter_best > WIN - 200 || iter_best < -WIN + 200) break;
        if (c->tid == 0 && (now_ms() - c->t0) * 100 > c->limit * SOFT_PCT) break;
    }
    c->bestr = bestr; c->bestsc = bestsc; c->bestdepth = bestdepth;
    c->nodes = nodes;
}

/* ---------------------------- so'rov va qidiruv ---------------------------- */
typedef struct { int nex; int ex[64][2]; int ns; uint64_t seenh[512]; } Req;
static Req g_req;

static void load_board(const char *bs) {
    for (int i = 0; i < 64; i++) {
        char ch = bs[i];
        B[i] = ch == 'o' ? 1 : ch == 'O' ? 2 : ch == 'x' ? -1 : ch == 'X' ? -2 : 0;
    }
    H = board_hash();
    MP = MN = MK = 0;
    NPCS = 0;
    for (int i = 0; i < 64; i++) {
        if (B[i]) NPCS++;
        if (B[i] > 0) MP |= 1ULL << i; else if (B[i] < 0) MN |= 1ULL << i;
        if (B[i] == 2 || B[i] == -2) MK |= 1ULL << i;
    }
}

static void read_req(Req *q) {
    q->nex = 0; q->ns = 0;
    if (scanf("%d", &q->nex) != 1) q->nex = 0;
    if (q->nex > 64) q->nex = 64;
    for (int i = 0; i < q->nex; i++) if (scanf("%d %d", &q->ex[i][0], &q->ex[i][1]) != 2) { q->nex = i; break; }
    if (scanf("%d", &q->ns) != 1) q->ns = 0;
    int ns = q->ns;
    for (int i = 0; i < ns; i++) {
        char t[256];
        if (scanf("%255s", t) != 1) { q->ns = i; break; }
        if (i < 512 && strlen(t) >= 64) {
            uint64_t h = 0;
            for (int k = 0; k < 64; k++) {
                int v = t[k] == 'o' ? 1 : t[k] == 'O' ? 2 : t[k] == 'x' ? -1 : t[k] == 'X' ? -2 : 0;
                if (v) h ^= ZB[zi(v)][k];
            }
            q->seenh[i] = h;
        } else if (i < 512) q->seenh[i] = 0;
    }
    if (q->ns > 512) q->ns = 512;
}

